"""Intent tests for mdata.validate_rows (DATA-02, TC-01)."""

from __future__ import annotations

import pytest

from mdata import RawRow, validate_rows


def _rows(triples: list[list]) -> list[RawRow]:
    return [RawRow(date=d, ticker=t, close=c) for d, t, c in triples]


@pytest.mark.intent
def test_tc01_drops_unusable_rows_keeps_later_duplicate_and_sorts(golden):
    data, expected = golden("mdata", "TC-01")
    result = validate_rows(_rows(data["rows"]), data["tickers"])
    assert result == _rows(expected["rows"])


@pytest.mark.intent
def test_tc01_result_is_a_list_of_raw_rows(golden):
    data, expected = golden("mdata", "TC-01")
    result = validate_rows(_rows(data["rows"]), data["tickers"])
    assert isinstance(result, list)
    assert len(result) == len(expected["rows"])
    assert all(isinstance(row, RawRow) for row in result)


@pytest.mark.intent
def test_tc01_default_tickers_matches_explicit_none(golden):
    data, expected = golden("mdata", "TC-01")
    result = validate_rows(_rows(data["rows"]))
    assert result == _rows(expected["rows"])


@pytest.mark.intent
def test_requested_ticker_absent_from_rows_is_key_error_naming_it(contract_sample):
    rows = [RawRow(**row) for row in contract_sample("mdata.RawRow")["rows"]]
    with pytest.raises(KeyError, match="ZZZ"):
        validate_rows(rows, ["A", "ZZZ"])


@pytest.mark.intent
def test_requested_ticker_with_only_unusable_rows_is_key_error_naming_it(contract_sample):
    rows = [RawRow(**row) for row in contract_sample("mdata.RawRow")["rows"]]
    rows += [
        RawRow(date="2024-03-04", ticker="QQQ", close=None),
        RawRow(date="2024-03-05", ticker="QQQ", close=0.0),
        RawRow(date="2024-03-06", ticker="QQQ", close=-3.0),
    ]
    with pytest.raises(KeyError, match="QQQ"):
        validate_rows(rows, ["A", "B", "QQQ"])

